#include <iostream>
#include <sstream>
#include <cstdint>

int main() {
    // Sử dụng std::stringstream chế độ binary để mô phỏng tệp nhị phân độc lập
    std::stringstream binaryStream(std::ios::in | std::ios::out | std::ios::binary);

    int32_t originalInt = 199;
    binaryStream.write(reinterpret_cast<const char*>(&originalInt), sizeof(originalInt));

    // Đặt lại con trỏ đọc về đầu luồng
    binaryStream.seekg(0, std::ios::beg);

    int32_t restoredInt = 0;
    binaryStream.read(reinterpret_cast<char*>(&restoredInt), sizeof(restoredInt));

    std::cout << "Bytes read: " << binaryStream.gcount() << "\n";
    std::cout << "Restored value: " << restoredInt << "\n";

    return 0;
}

#include <iostream>
#include <sstream>
#include <cstring>

// Lớp bản ghi kích thước cố định phục vụ lưu trữ nhị phân trực tiếp
class Student {
private:
    char firstName[25];
    char mi;
    char lastName[25];
    int score;

public:
    Student() : mi(' '), score(0) {
        firstName[0] = '\0';
        lastName[0] = '\0';
    }

    Student(const char* fn, char m, const char* ln, int s) : mi(m), score(s) {
        std::strncpy(firstName, fn, sizeof(firstName) - 1);
        firstName[sizeof(firstName) - 1] = '\0';
        std::strncpy(lastName, ln, sizeof(lastName) - 1);
        lastName[sizeof(lastName) - 1] = '\0';
    }

    void display() const {
        std::cout << firstName << " " << mi << " " << lastName << " " << score << "\n";
    }
};

int main() {
    std::stringstream stream(std::ios::in | std::ios::out | std::ios::binary);

    // 1. Ghi và đọc mảng số thực
    double scores[3] = {3.4, 2.5, 6.9};
    stream.write(reinterpret_cast<const char*>(scores), sizeof(scores));

    // 2. Ghi đối tượng bản ghi kích thước cố định
    Student s1("John", 'T', "Smith", 90);
    stream.write(reinterpret_cast<const char*>(&s1), sizeof(Student));

    // Di chuyển con trỏ đọc về đầu luồng
    stream.seekg(0, std::ios::beg);

    double readScores[3] = {0.0, 0.0, 0.0};
    stream.read(reinterpret_cast<char*>(readScores), sizeof(readScores));

    Student readStudent;
    stream.read(reinterpret_cast<char*>(&readStudent), sizeof(Student));

    for (int i = 0; i < 3; i++) {
        std::cout << readScores[i] << " ";
    }
    std::cout << "\n";
    readStudent.display();

    return 0;
}
